import{_ as a,C as t,o as n,c as r,ag as s,E as i}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Commission Management","description":"","frontmatter":{},"headers":[],"relativePath":"payments/commission-management.md","filePath":"payments/commission-management.md","lastUpdated":1786088921000}'),l={name:"payments/commission-management.md"};function m(c,e,h,d,g,p){const o=t("ImagePopup");return n(),r("div",null,[e[0]||(e[0]=s('<h1 id="commission-management" tabindex="-1">Commission Management <a class="header-anchor" href="#commission-management" aria-label="Permalink to &quot;Commission Management&quot;">​</a></h1><p>Commission is how the marketplace earns from each sale. On every seller order, the platform keeps a percentage as commission and the seller receives the rest. The admin sets the rates; the split is calculated automatically on each order, at the moment of sale.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where the global commission rate is set</li><li>How per-seller rates override the default</li><li>How commission is calculated and where it shows up</li></ul></div><h2 id="the-global-commission-rate" tabindex="-1">The global commission rate <a class="header-anchor" href="#the-global-commission-rate" aria-label="Permalink to &quot;The global commission rate&quot;">​</a></h2><p>Go to <strong>Configure → Marketplace → General</strong>. The <strong>Admin Commission Percentage</strong> is the default rate applied to seller sales across the marketplace — for example, <strong>20%</strong> means the platform keeps 20% of a sale and the seller earns the other 80%.</p>',5)),i(o,{src:"/images/commission-management/commission-config.png",alt:"Admin Commission Percentage setting"}),e[1]||(e[1]=s('<p>The same screen also carries the marketplace <strong>status</strong>, the <strong>seller panel logo</strong>, the <strong>subscription</strong> switch, and the installed <strong>module version</strong>.</p><h2 id="per-seller-commission" tabindex="-1">Per-seller commission <a class="header-anchor" href="#per-seller-commission" aria-label="Permalink to &quot;Per-seller commission&quot;">​</a></h2><p>The global percentage is the default, but the admin can give an individual seller a <strong>different rate</strong> on that seller&#39;s admin edit form — <strong>Commission Enabled</strong> plus a <strong>Commission Percentage</strong> (see <a href="/sellers/seller-management#editing-a-seller">Seller Management</a>). When enabled, the seller&#39;s own rate overrides the global default — useful for negotiated terms or preferred partners. A <a href="/subscriptions/seller-subscription-management">subscription plan</a> can also set a seller&#39;s commission when they subscribe.</p><h2 id="how-commission-is-calculated" tabindex="-1">How commission is calculated <a class="header-anchor" href="#how-commission-is-calculated" aria-label="Permalink to &quot;How commission is calculated&quot;">​</a></h2><p>Commission is worked out <strong>per order item</strong> when the order is placed, and the rate is <strong>frozen onto the order</strong> so later changes to the config or the seller don&#39;t retro-alter past orders:</p><ul><li><strong>Commission</strong> = the item&#39;s total (after any discount) × the applicable rate.</li><li><strong>Seller earning</strong> = the item&#39;s total − commission + tax (the seller keeps the tax).</li></ul><p>At invoice time, commission is recomputed on the <strong>net invoiced amount</strong> (after discount) — so a seller is never charged commission on discount money the customer didn&#39;t actually pay.</p><h2 id="where-commission-shows-up" tabindex="-1">Where commission shows up <a class="header-anchor" href="#where-commission-shows-up" aria-label="Permalink to &quot;Where commission shows up&quot;">​</a></h2><ul><li>On the <strong><a href="/orders/order-management">order list and detail</a></strong>, alongside each order&#39;s gross amount and the seller&#39;s earning.</li><li>On the <strong><a href="/payments/payment-management">Seller Payout Management</a></strong> view — the <strong>Total Commission Earned</strong> card and each order&#39;s figures.</li><li>On each <strong><a href="/payments/payment-management#transactions">transaction</a></strong>, broken out per item.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set the global <strong>Admin Commission Percentage</strong> as your baseline, then adjust individual sellers only where you&#39;ve agreed a special rate — it keeps the platform&#39;s economics simple and predictable.</p></div>',10))])}const b=a(l,[["render",m]]);export{f as __pageData,b as default};
